async function load() {
  try {
    return Promise.reject('offline');
  } catch {
    console.log('inner-catch');
    return 'cached';
  } finally {
    console.log('inner-finally');
  }
}

load()
  .catch((error) => {
    console.log(`outer:${error}`);
    return 'queued';
  })
  .finally(() => console.log('outer-finally'))
  .then((value) => console.log(`value:${value}`));
